const groups = [];

const uniqueText = values => [...new Set(values.flatMap(value => Array.isArray(value) ? value : [value]).map(value => String(value ?? '').trim()).filter(value => value && value !== '-'))];
const cloudSection = key => exportCloudSnapshot()[key];
const arrayRows = key => { const value=cloudSection(key); return Array.isArray(value) ? value : []; };
const objectRows = key => { const value=cloudSection(key); return value && typeof value==='object' && !Array.isArray(value) ? value : {}; };
const valuesAt = (key,indexes=[0]) => arrayRows(key).flatMap(row => Array.isArray(row) ? indexes.map(index=>row[index]) : []);

function databaseSuggestions(label=''){
  const name=String(label).replaceAll('*','').trim().toLowerCase();
  let values=[];
  const products=arrayRows('dfab-erp-products-v3');
  const customers=arrayRows('dfab-erp-customers-v2');
  const vendors=arrayRows('dfab-erp-vendors-v2');
  const productDetails=objectRows('dfab-erp-products-details-v1');
  if(/product code|item code|raw material code/.test(name)) values.push(...products.map(r=>r?.[0]));
  else if(/product|item|material|raw material/.test(name)) values.push(...products.flatMap(r=>[r?.[0],r?.[1]]));
  if(/customer|consignee|party/.test(name)) values.push(...customers.flatMap(r=>[r?.[0],r?.[1]]));
  if(/vendor|supplier/.test(name)) values.push(...vendors.flatMap(r=>[r?.[0],r?.[1]]));
  if(/account/.test(name)) values.push(...customers.flatMap(r=>[r?.[0],r?.[1]]),...vendors.flatMap(r=>[r?.[0],r?.[1]]));
  if(/group/.test(name)) values.push(...arrayRows('dfab-erp-product-groups-v2').map(r=>typeof r==='string'?r:r?.name),...products.map(r=>r?.[3]));
  if(/uom|unit/.test(name)) values.push(...valuesAt('dfab-erp-uoms',[0,1]),...valuesAt('dfab-erp-UOM',[0,1,2]),...products.map(r=>r?.[4]));
  if(/type/.test(name)&&/product/.test(name)) values.push(...valuesAt('dfab-erp-product-types',[0]),...valuesAt('dfab-erp-Types',[0,1]),...products.map(r=>r?.[2]));
  if(/category/.test(name)) values.push(...valuesAt('dfab-erp-product-categories',[0,1]),...valuesAt('dfab-erp-Categories',[0,1]));
  if(/hsn/.test(name)) values.push(...valuesAt('dfab-erp-hsn-master',[0]),...valuesAt('dfab-erp-HSN Master',[0]));
  if(/process|operation/.test(name)) values.push(...valuesAt('dfab-erp-Process Master',[0,1]), ...arrayRows('dfab-live-process').flatMap(r=>[r.code,r.description]));
  if(/machine|work ?center/.test(name)) values.push(...valuesAt('dfab-erp-WorkCenter/Machine Master',[0,1]), ...arrayRows('dfab-live-workcenters').flatMap(r=>[r.code,r.description]), ...arrayRows('dfab-live-machines').flatMap(r=>[r.code,r.description]));
  if(/department/.test(name)) values.push(...arrayRows('dfab-live-departments').map(r=>typeof r==='string'?r:r?.name),...valuesAt('dfab-erp-Department Master',[0,1]));
  if(/user|employee|owner|inspector|requested by|approved by|assigned by|reviewed by|calibrated by/.test(name)) values.push(...valuesAt('dfab-erp-Users',[0,1]),...arrayRows('dfab-live-department-users').flatMap(r=>r&&typeof r==='object'?[r.username]:[]));
  if(/work order|wo no/.test(name)) values.push(...valuesAt('dfab-erp-Work Order',[0]));
  if(/sales order|so no/.test(name)) values.push(...valuesAt('dfab-erp-Sales Orders',[0]));
  if(/purchase order|po no/.test(name)) values.push(...valuesAt('dfab-erp-Purchase Orders',[0]));
  if(/grn/.test(name)) values.push(...valuesAt('dfab-erp-GRN',[0]));
  if(/output no/.test(name)) values.push(...valuesAt('dfab-erp-Production Output',[0]));
  if(/issue dc/.test(name)) values.push(...valuesAt('dfab-erp-Outsource Issue DC',[0]));
  if(/inward no/.test(name)) values.push(...valuesAt('dfab-erp-Job Work Inward',[0]));
  if(/^qc no$|inspection no/.test(name)) values.push(...valuesAt('dfab-erp-Inward QC',[0]),...valuesAt('dfab-erp-Outward QC',[0]));
  if(/^dc no$|delivery challan/.test(name)) values.push(...valuesAt('dfab-erp-Delivery Challan',[0]));
  if(/enquiry/.test(name)) values.push(...valuesAt('dfab-erp-Sales Enquiries',[0]));
  if(/quotation/.test(name)) values.push(...valuesAt('dfab-erp-Sales Quotations',[0]));
  if(/invoice/.test(name)) values.push(...arrayRows('dfab-erp-sales-invoices-v2').map(r=>r?.[1]),...valuesAt('dfab-erp-Purchase',[0]));
  if(/transaction number|transaction record|reference no|reference$/.test(name)) ['Sales Enquiries','Sales Quotations','Sales Orders','Purchase Orders','GRN','Work Order','Material Request','Material Issue','Route Cards','Production Output','Delivery Challan','Vendor Payments','Customer Payments'].forEach(module=>values.push(...valuesAt(`dfab-erp-${module}`,[0])));
  if(/bom/.test(name)) values.push(...valuesAt('dfab-erp-production-bom-v2',[0]));
  if(/route card|linked route/.test(name)) values.push(...valuesAt('dfab-erp-route-card-v2',[0]));
  if(/location|store/.test(name)) values.push(...Object.values(productDetails).flatMap(d=>d?.location?[d.location]:[]));
  return uniqueText(values).slice(0,250);
}

function productFromDatabase(value=''){
  const term=String(value).trim().toLowerCase();
  return arrayRows('dfab-erp-products-v3').find(r=>String(r?.[0]||'').toLowerCase()===term||String(r?.[1]||'').toLowerCase()===term);
}

function findCloudRow(key,value,indexes=[0]){
  const term=String(value??'').trim().toLowerCase();
  if(!term)return null;
  return arrayRows(key).find(row=>Array.isArray(row)&&indexes.some(index=>String(row?.[index]??'').trim().toLowerCase()===term))||null;
}

function referenceAutofill(label,value){
  const name=String(label).replaceAll('*','').trim().toLowerCase();
  let row=null,data={};
  if(/enquiry/.test(name)){
    row=findCloudRow('dfab-erp-Sales Enquiries',value);if(row)data={Customer:row[1],Product:row[2],Item:row[2],Qty:row[3],'Expected Delivery':row[4]};
  }else if(/quotation no/.test(name)){
    row=findCloudRow('dfab-erp-Sales Quotations',value);if(row)data={Customer:row[1],Enquiry:row[2],Amount:row[3]};
  }else if(/sales order|so no/.test(name)){
    row=findCloudRow('dfab-erp-Sales Orders',value);if(row)data={Customer:row[1],Product:row[3],Item:row[3],Qty:row[4],Delivery:row[5]};
  }else if(/work order|wo no/.test(name)){
    row=findCloudRow('dfab-erp-Work Order',value);if(row)data={'SO No':row[1],Product:row[2],Item:row[2],Material:row[2],Qty:row[3],Machine:row[4]};
  }else if(/purchase order|po no/.test(name)){
    row=findCloudRow('dfab-erp-Purchase Orders',value);if(row)data={Vendor:row[1],'PO Date':row[2],Amount:row[3],'Delivery Date':row[4]};
  }else if(/grn no|^grn$/.test(name)){
    row=findCloudRow('dfab-erp-GRN',value);if(row)data={'PO No':row[1],Vendor:row[2],Item:row[3],Product:row[3],Qty:row[4],'Received Qty':row[4]};
  }else if(/output no/.test(name)){
    row=findCloudRow('dfab-erp-Production Output',value);if(row)data={'WO No':row[1],Product:row[2],Item:row[2],Qty:row[3],'Good Qty':row[3]};
  }else if(/issue dc/.test(name)){
    row=findCloudRow('dfab-erp-Outsource Issue DC',value);if(row)data={Vendor:row[1],'Work Order':row[2],Process:row[3],Qty:row[4]};
  }else if(/inward no/.test(name)){
    row=findCloudRow('dfab-erp-Job Work Inward',value);if(row)data={Customer:row[1],Product:row[3],Material:row[3],Qty:row[4]};
  }else if(/purchase invoice/.test(name)){
    row=findCloudRow('dfab-erp-Purchase',value);if(row)data={Vendor:row[1],'PO No':row[2],Amount:row[4]};
  }else if(/invoice/.test(name)){
    row=findCloudRow('dfab-erp-sales-invoices-v2',value,[1]);if(row)data={Customer:row[3],Amount:row[7]};
  }
  const product=productFromDatabase(value);
  if(product)data={...data,'Product Code':product[0],Product:product[1]||product[0],Item:product[1]||product[0],Material:product[1]||product[0],UOM:product[4],Group:product[3],'Product Group':product[3]};
  return Object.fromEntries(Object.entries(data).filter(([,item])=>item!==undefined&&item!==null&&String(item).trim()!==''));
}

function DatabaseSuggestInput({label,value,onChange,type='text',placeholder='',min,step,max,required=false,className='',onResolved}){
  const suggestions=type==='text'||type==='email'?databaseSuggestions(label):[];
  const listId=`erp-list-${String(label).replace(/[^a-z0-9]/gi,'-').toLowerCase()}`;
  const resolve=e=>{onChange(e);if(onResolved){const product=productFromDatabase(e.target.value);onResolved(e.target.value,product)}};
  return <><input className={className} required={required} list={suggestions.length?listId:undefined} type={type} value={value??''} placeholder={placeholder} min={min} max={max} step={step} onChange={resolve}/>{suggestions.length>0&&<datalist id={listId}>{suggestions.map(option=><option key={option} value={option}/>)}</datalist>}</>;
}

function collectDatabaseNotifications(){
  const snapshot=exportCloudSnapshot();const result=[];const seen=new Set();
  const push=(module,reference,status,page=module)=>{const key=`${module}|${reference}|${status}`;if(seen.has(key))return;seen.add(key);result.push({module,reference:String(reference||'Record'),status:String(status||'Pending'),page})};
  for(const [key,value] of Object.entries(snapshot)){
    if(!Array.isArray(value)||!key.startsWith('dfab-'))continue;
    const pageMap={'dfab-erp-products-v3':'Products','dfab-erp-customers-v2':'Customers','dfab-erp-vendors-v2':'Vendors','dfab-erp-production-bom-v2':'Production BOM','dfab-erp-route-card-v2':'Route Card','dfab-live-instruments':'Instrument Master','dfab-live-daily-tasks':'Daily Task Master'};const module=pageMap[key]||key.replace(/^dfab-(?:erp|live)-/,'').replace(/-v\d+$/,'').replaceAll('-',' ');
    for(const row of value){
      if(!Array.isArray(row)||!row.length)continue;
      const status=String(row.at(-1)||'').toUpperCase();
      if(/APPROVAL PENDING|PENDING APPROVAL|REJECTED|QC PENDING|CALIBRATION DUE/.test(status))push(module,row[0]||row[1],row.at(-1),module);
    }
  }
  const approvals=arrayRows('dfab-erp-Pending Approvals');
  approvals.forEach(row=>{if(Array.isArray(row)&&String(row.at(-1)||'').toLowerCase()==='pending')push(row[0]||'Pending Approvals',row[1]||row[0],row.at(-1),'Pending Approvals')});
  return result.slice(0,50);
}

