const pageAliases = { List:'Products', Groups:'Groups' };
const displayPageNames = { 'Vendor Price List Report':'Vendor Price List' };
const resolvePage = (name) => pageAliases[name] || name;
const normalizeNode = (node) => Array.isArray(node) ? {label:node[0],icon:node[1],children:null,page:null} : node;

// UI-only sidebar accordion helpers. Page content and business flows remain untouched.
const menuStateForPath = (path='') => {
  if(!path)return {};
  const parts=path.split('/').filter(Boolean);const next={};
  for(let i=1;i<=parts.length;i++)next[parts.slice(0,i).join('/')]=true;
  return next;
};
const findMenuParentPath = (target,nodes=menuTree,parentPath='') => {
  const resolvedTarget=resolvePage(target);
  for(const raw of nodes){
    const node=normalizeNode(raw);const key=parentPath?`${parentPath}/${node.label}`:node.label;
    if(Array.isArray(node.children)){
      const found=findMenuParentPath(target,node.children,key);if(found!==null)return found;
    }else if(resolvePage(node.page||node.label)===resolvedTarget){return parentPath;}
  }
  return null;
};

