  , 'Seal Uploads': {columns:['Seal No','Product','Drawing / Document','Uploaded By','Status'],fields:['Seal No','Product','Drawing / Document','Uploaded By'],statuses:['Draft','Verified','Approved']}
  , 'Instrument Master': {columns:['Instrument Code','Instrument Name','Range','Calibration Due','Status'],fields:['Instrument Code','Instrument Name','Range','Calibration Due'],statuses:['Active','Calibration Due','Inactive']}
  , 'Department Master': {columns:['Department Code','Department Name','Head','Cost Center','Status'],fields:['Department Code','Department Name','Head','Cost Center'],statuses:['Active','Inactive']}
  , 'Quality Master': {columns:['Plan Code','Quality Plan','Product Group','Revision','Status'],fields:['Plan Code','Quality Plan','Product Group','Revision'],statuses:['Draft','Approved','Inactive']}
  , 'Daily Task Master': {columns:['Task Code','Task','Department','Frequency','Status'],fields:['Task Code','Task','Department','Frequency'],statuses:['Active','Inactive']}
  , 'Asset Allocation': {columns:['Allocation No','Asset','Employee','Allocated Date','Status'],fields:['Allocation No','Asset','Employee','Allocated Date'],statuses:['Allocated','Returned','Maintenance']}
  , 'Kind Attention': {columns:['Code','Contact Person','Company','Designation','Status'],fields:['Code','Contact Person','Company','Designation'],statuses:['Active','Inactive']}
  , 'Remark Master': {columns:['Remark Code','Remark','Module','Status'],fields:['Remark Code','Remark','Module'],statuses:['Active','Inactive']}
  , 'General Task': {columns:['Task No','Task','Owner','Due Date','Status'],fields:['Task No','Task','Owner','Due Date'],statuses:['Open','In Progress','Completed']}
  , 'PO Number Details': {columns:['PO Number','Customer','PO Date','Value','Status'],fields:['PO Number','Customer','PO Date','Value'],statuses:['Open','Consumed','Closed']}
  , 'Process Price List': {columns:['Price Ref','Process','Vendor','Rate','Effective Date','Status'],fields:['Price Ref','Process','Vendor','Rate','Effective Date'],statuses:['Draft','Active','Expired']}
  , 'RM Inward and Outward': {columns:['Entry No','Raw Material','Inward Qty','Outward Qty','Balance','Date'],fields:['Entry No','Raw Material','Inward Qty','Outward Qty','Balance','Date']}
  , 'SO Number Details': {columns:['SO Number','Customer','Product','Qty','Delivery Date','Status'],fields:['SO Number','Customer','Product','Qty','Delivery Date'],statuses:['Open','In Production','Completed']}
  , 'Vendor Price List': {columns:['Price Ref','Vendor','Item','UOM','Rate','Valid Until','Status'],fields:['Price Ref','Vendor','Item','UOM','Rate','Valid Until'],statuses:['Draft','Active','Expired']}
  , 'Customer Price List': {columns:['Price Ref','Customer','Product','UOM','Rate','Valid Until','Status'],fields:['Price Ref','Customer','Product','UOM','Rate','Valid Until'],statuses:['Draft','Active','Expired']}
  , 'Purchase': {columns:['Invoice No','Vendor','PO No','Invoice Date','Taxable Amount','Status'],fields:['Invoice No','Vendor','PO No','Invoice Date','Taxable Amount'],statuses:['Draft','QC Cleared','Posted','Paid'],next:'Vendor Payments'}
  , 'Tally Link - Purchase': {columns:['Voucher No','Purchase Invoice','Vendor','Amount','Sync Status'],fields:['Voucher No','Purchase Invoice','Vendor','Amount'],statuses:['Pending','Synced','Failed']}
  , 'Tally Link - Sales': {columns:['Voucher No','Sales Invoice','Customer','Amount','Sync Status'],fields:['Voucher No','Sales Invoice','Customer','Amount'],statuses:['Pending','Synced','Failed']}
