function buildHomeSuggestions(goToPage){
  const counts={
    products: arrayRows('dfab-erp-products-v3').length,
    customers: arrayRows('dfab-erp-customers-v2').length,
    vendors: arrayRows('dfab-erp-vendors-v2').length,
    boms: arrayRows('dfab-erp-production-bom-v2').length,
    routes: arrayRows('dfab-erp-route-card-v2').length,
    enquiries: arrayRows('dfab-erp-Sales Enquiries').length,
    quotations: arrayRows('dfab-erp-Sales Quotations').length,
    salesOrders: arrayRows('dfab-erp-Sales Orders').length,
    workOrders: arrayRows('dfab-erp-Work Order').length,
    pos: arrayRows('dfab-erp-Purchase Orders').length,
    grns: arrayRows('dfab-erp-GRN').length,
    invoices: arrayRows('dfab-erp-sales-invoices-v2').length,
  };
  const suggestions=[];
  if(!counts.products) suggestions.push({title:'Create Product Master', text:'Start by adding products so every commercial, stores and production transaction can reference a valid item.', page:'Products', tone:'warning'});
  if(counts.products && (!counts.boms || !counts.routes)) suggestions.push({title:'Finish Engineering Masters', text:'Products are available. Complete Production BOM and Route Card so Work Orders and production output can flow properly.', page:!counts.boms?'Production BOM':'Route Card', tone:'info'});
  if(counts.products && (!counts.customers || !counts.vendors)) suggestions.push({title:'Complete Account Masters', text:'Maintain both customers and vendors to unlock sales, procurement, invoice and payment flows end-to-end.', page:!counts.customers?'Customers':'Vendors', tone:'warning'});
  if(counts.products && counts.customers && !counts.enquiries) suggestions.push({title:'Start the Sales Flow', text:'Raise a Sales Enquiry and progress it to quotation and order so the downstream workflow can be tested properly.', page:'Sales Enquiries', tone:'success'});
  if(counts.salesOrders && !counts.workOrders) suggestions.push({title:'Release Work Orders', text:'Sales orders are present. Generate linked work orders to move into material request, issue and production.', page:'Work Order', tone:'info'});
  if(counts.pos && !counts.grns) suggestions.push({title:'Receive Procured Material', text:'Purchase Orders exist. Post GRN and inward QC so the items can reach stock correctly.', page:'GRN', tone:'info'});
  if(counts.quotations && !counts.salesOrders) suggestions.push({title:'Convert Quotations to Orders', text:'Commercial quotations are available. Move confirmed quotations into Sales Orders to continue the operational chain.', page:'Sales Orders', tone:'success'});
  if(counts.workOrders && !counts.invoices) suggestions.push({title:'Continue to Dispatch & Billing', text:'Work orders exist. Complete production, outward QC, delivery challan and invoice to close the order-to-cash cycle.', page:'Production Output', tone:'info'});
  return suggestions.slice(0,4);
}

function enterpriseDashboardData(){
  const approvals=readStored('dfab-erp-Pending Approvals',[]);
  const salesOrders=readStored('dfab-erp-Sales Orders',[]);
  const purchaseOrders=readStored('dfab-erp-Purchase Orders',[]);
  const workOrders=readStored('dfab-erp-Work Order',[]);
  const qc=[...readStored('dfab-erp-Inward QC',[]),...readStored('dfab-erp-Outward QC',[])];
  const pendingApprovals=approvals.filter(r=>String(r?.at?.(-1)||r?.[4]||'').toLowerCase().includes('pending')).length;
  const activeSales=salesOrders.filter(r=>!/closed|completed|cancel/i.test(String(r?.at?.(-1)||''))).length;
  const openPO=purchaseOrders.filter(r=>!/closed|completed|cancel/i.test(String(r?.at?.(-1)||''))).length;
  const activeWO=workOrders.filter(r=>!/closed|completed|cancel/i.test(String(r?.at?.(-1)||''))).length;
  const qcPending=qc.filter(r=>/pending|await/i.test(String(r?.at?.(-1)||''))).length;
  return {pendingApprovals,activeSales,openPO,activeWO,qcPending};
}

