function StatCards({items,onSelect}){const selectCard=(index,label)=>{if(!onSelect)return;onSelect(index,label);requestAnimationFrame(()=>requestAnimationFrame(()=>{const content=document.querySelector('.page-transition-shell>.content');const sheet=content?.querySelector('[data-status-sheet="true"]');if(content&&sheet)content.scrollTo({top:Math.max(0,sheet.offsetTop-8),behavior:'smooth'})}))};return <div className="stat-cards">{items.map(({label,value,icon:Icon,tone,clickable=true},index)=>{const canSelect=!!onSelect&&clickable!==false;return <div className={`stat-card ${tone} ${canSelect?'stat-clickable':''}`} key={label} role={canSelect?'button':undefined} tabIndex={canSelect?0:undefined} onClick={()=>canSelect&&selectCard(index,label)} onKeyDown={e=>{if(canSelect&&(e.key==='Enter'||e.key===' ')){e.preventDefault();selectCard(index,label)}}}><Icon size={30}/><div className="stat-label">{label}</div><div className="stat-value">{value}</div></div>})}</div>}

