function useStoredRows(key,initial){
  const [state,setState]=useState(()=>({key,rows:readStored(key,initial)}));
  if(state.key!==key)setState({key,rows:readStored(key,initial)});
  useEffect(()=>{if(state.key===key)writeStored(key,state.rows)},[key,state]);
  const setRows=value=>setState(previous=>({key,rows:typeof value==='function'?value(previous.key===key?previous.rows:readStored(key,initial)):value}));
  return [state.key===key?state.rows:readStored(key,initial),setRows];
}
