  const [materials,setMaterials]=useStoredRows('dfab-live-quality-materials',[]);const [wps,setWps]=useStoredRows('dfab-live-quality-wps',[]);const [electrodes,setElectrodes]=useStoredRows('dfab-live-quality-electrodes',[]);const [modal,setModal]=useState('');const [form,setForm]=useState({});
  const save=()=>{if(modal==='material'){if(!form.name?.trim())return alert('Material Name is required.');setMaterials(v=>[...v,form.name.trim()])}else if(modal==='wps'){if(!form.material||!form.name?.trim())return alert('Material and WPS Name are required.');setWps(v=>[...v,{material:form.material,name:form.name}])}else{if(!form.material||!form.name?.trim())return alert('Material and Electrode Name are required.');setElectrodes(v=>[...v,{material:form.material,wps:form.wps||'-',name:form.name}])}setModal('');setForm({})};
